SELECT COUNT(*)
FROM groupbuy_team t
JOIN groupbuy_campaign c ON c.id=t.campaign_id
JOIN shop s ON s.id=c.shop_id
WHERE t.region=#{region} AND c.region=#{region} AND s.region=#{region}
AND t.status=#{status}

SELECT 
FROM groupbuy_team t
JOIN groupbuy_campaign c ON c.id=t.campaign_id
JOIN shop s ON s.id=c.shop_id
WHERE t.region=#{region} AND c.region=#{region} AND s.region=#{region}
AND t.status=#{status}


